/**
 * Create the demo film if it is not already there.
 *
 * Returns the project id either way, so the landing page always has something
 * to link to. Every failure is swallowed and logged: a demo that cannot be
 * seeded is a missing sample, not a reason for the server not to start.
 */
export async function ensureDemoProject() {
  const existing = await one('SELECT id FROM projects WHERE is_demo = 1')
  if (existing) return existing.id

  const ts = now()
  const projectId = uid()

  await insert('projects', {
    id: projectId,
    owner_id: null,
    is_demo: 1,
    name: DEMO_NAME,
    format: 'cinematic short',
    status: 'Creative Development',
    logline: 'A man who stopped a distillery twenty years ago is handed a notebook in handwriting he does not recognise.',
    core_emotion: 'the quiet after something is found out',
    created_at: ts, updated_at: ts,
  })

  await insert('idea', {
    project_id: projectId,
    raw_text:
      'A distillery above a village, cold for twenty years. The man who stopped it still walks the floor every ' +
      'morning and touches nothing. His partner’s daughter comes back with her father’s notebook and the ' +
      'handwriting in it is not her father’s. I want the whole film to feel like the minute before someone ' +
      'decides to say something. Copper, wet stone, one shaft of light per bay.',
    updated_at: ts,
  })

  await insert('story', {
    project_id: projectId,
    premise: 'Two people discover that the reason a distillery closed was never the reason they were told.',
    logline: 'A man who stopped a distillery twenty years ago is handed a notebook in handwriting he does not recognise.',
    beginning: 'Tomas opens the still house before dawn, as he has every morning for twenty years, and turns nothing on.',
    middle: 'Ilse arrives from the city with her late father’s notebook. Tomas reads two lines and stops.\n\n'
      + 'Neither of them says what they have both understood. They stand in the yard in the rain instead.',
    ending: 'Tomas lights the fire under the wash still for the first time in twenty years. Ilse watches and does not ask why.',
    characters: 'Tomas, who stopped it. Ilse, who was told a story about why.',
    conflict: 'The truth is available to both of them and neither will be the one to say it aloud.',
    theme: 'What it costs to keep someone else’s secret past their death.',
    emotional_journey: 'dormancy → trespass → the floor going → a decision made without discussion',
    message: 'Some things are restarted rather than explained.',
    visual_motifs: 'cold copper, single shafts of window light, the unopened spirit safe, rain that never becomes weather',
    updated_at: ts,
  })

  await insert('director_vision', {
    project_id: projectId,
    genre: 'quiet drama',
    tone: 'restrained, mineral, unsentimental',
    emotional_journey: 'Start dormant. Let one discovery move the floor. End on an action, not a line.',
    pacing: 'Slow, but never idle. Every held frame is held because something is being decided in it.',
    camera_philosophy:
      'Locked off unless a move is motivated by a character. The camera waits; it does not hunt. '
      + 'Wides for the building, long lenses for faces, nothing in between.',
    performance_direction: 'Under. Always under. The scene is what they decline to say.',
    editing_philosophy: 'Cut late. Let shots outstay their information by a beat.',
    locked: 0,
    updated_at: ts,
  })

  await insert('visual_dna', {
    id: uid(), project_id: projectId, version: 1, is_current: 1, locked: 0, label: 'Initial',
    film_character: 'photochemical, fine grain, slight halation in the highlights',
    color: 'desaturated slate and moss, with copper and oxblood as the only warm values',
    contrast: 'low-contrast mids, protected highlights, shadows that go genuinely black',
    texture: 'wet stone, oxidised metal, cotton paper',
    lighting: 'single-source and directional indoors; flat overcast outdoors. Never a fill you can name.',
    atmosphere: 'cold air made visible — breath, dust, fine rain',
    camera: 'static frames, 35mm for space and 85mm for faces, no zooms',
    depth: 'deep for the building, shallow for hands and faces',
    image_quality: 'anamorphic softness at the edges, sharp centre',
    avoid: 'warm fill light, lens flare, drone shots, colour grading toward teal and orange, visible camera shake',
    created_at: ts, updated_at: ts,
  })

  /* ----------------------- world bible ----------------------- */
  const entityIds = new Map()
  const seedEntities = async (table, rows, kind) => {
    for (const [i, row] of rows.entries()) {
      const id = uid()
      await insert(table, { id, project_id: projectId, sort: i + 1, locked: 0, updated_at: ts, ...row })
      entityIds.set(row.name, { kind, id })
    }
  }
  await seedEntities('characters', CHARACTERS, 'character')
  await seedEntities('locations', LOCATIONS, 'location')
  await seedEntities('props', PROPS, 'prop')

  /* -------------------- scenes, shots, prompts -------------------- */
  let shotNumber = 0
  for (const [sceneIndex, sceneSpec] of SCENES.entries()) {
    const sceneId = uid()
    const location = entityIds.get(sceneSpec.location)
    await insert('scenes', {
      id: sceneId, project_id: projectId,
      number: sceneIndex + 1, sort: sceneIndex + 1,
      title: sceneSpec.title,
      location_id: location?.id ?? null,
      location_text: sceneSpec.location,
      time_of_day: sceneSpec.time_of_day,
      duration: sceneSpec.duration,
      story_purpose: sceneSpec.story_purpose,
      emotional_purpose: sceneSpec.emotional_purpose,
      description: sceneSpec.description,
      updated_at: ts,
    })
    await insert('scene_dna', {
      scene_id: sceneId, mode: 'extend', locked: 0, updated_at: ts, ...sceneSpec.dna,
    })
    if (location) {
      await insert('entity_links', {
        id: uid(), owner_type: 'scene', owner_id: sceneId,
        entity_type: 'location', entity_id: location.id,
      })
    }

    for (const [shotIndex, shotSpec] of sceneSpec.shots.entries()) {
      const { entities, ...fields } = shotSpec
      const shotId = uid()
      await insert('shots', {
        id: shotId, project_id: projectId, scene_id: sceneId,
        number: ++shotNumber, sort: shotIndex + 1,
        status: 'draft', updated_at: ts, ...fields,
      })
      for (const name of entities ?? []) {
        const hit = entityIds.get(name)
        if (!hit) continue
        await insert('entity_links', {
          id: uid(), owner_type: 'shot', owner_id: shotId,
          entity_type: hit.kind, entity_id: hit.id,
        })
      }
    }
  }

  // Compose a prompt for every shot, so the Prompt Lab has something to show
  // on arrival. This is the deterministic engine — no model is involved.
  await composeDemoPrompts(projectId, ts)

  return projectId
}

/** Build and store the current prompt for every demo shot. */
async function composeDemoPrompts(projectId, ts) {
  const project = await one('SELECT * FROM projects WHERE id = ?', projectId)
  const vision = await one('SELECT * FROM director_vision WHERE project_id = ?', projectId)
  const dna = await one('SELECT * FROM visual_dna WHERE project_id = ? AND is_current = 1', projectId)
  const shots = await all('SELECT * FROM shots WHERE project_id = ? ORDER BY sort', projectId)

  for (const shot of shots) {
    const scene = await one('SELECT * FROM scenes WHERE id = ?', shot.scene_id)
    const sceneDna = await one('SELECT * FROM scene_dna WHERE scene_id = ?', shot.scene_id)
    const links = await all(
      'SELECT * FROM entity_links WHERE owner_type = ? AND owner_id = ?', 'shot', shot.id)

    const pick = async (kind, table) => {
      const rows = await Promise.all(links.filter((l) => l.entity_type === kind)
        .map((l) => one(`SELECT * FROM ${table} WHERE id = ?`, l.entity_id)))
      return rows.filter(Boolean)
    }
    const locations = await pick('location', 'locations')
    if (!locations.length && scene?.location_id) {
      const l = await one('SELECT * FROM locations WHERE id = ?', scene.location_id)
      if (l) locations.push(l)
    }

    const built = composePrompt({
      project, vision, dna, scene, sceneDna, shot,
      characters: await pick('character', 'characters'),
      locations,
      props: await pick('prop', 'props'),
    })

    await insert('prompts', {
      id: uid(), shot_id: shot.id, version: 1, is_current: 1,
      body: built.body, negative: built.negative,
      layers_json: JSON.stringify(built.layers ?? []),
      hand_edited: 0, created_at: ts,
    })
  }
}
